"use client";

import { useState } from "react";
import { useLang } from "@/lib/lang-context";

/* ─────────────────────────────────────────────────────────
 * SEARCH — command search with live filtering.
 * The field, clear action, and results are directly usable.
 * ───────────────────────────────────────────────────────── */

const ITEMS = [
  { en: "Forecast summer demand", zh: "预测夏季需求" },
  { en: "Find waffle cone suppliers", zh: "寻找华夫脆筒供应商" },
  { en: "Compare seasonal flavors", zh: "对比季节限定口味" },
  { en: "Draft flavor launch plan", zh: "起草新口味上市计划" },
  { en: "Check cold-chain status", zh: "检查冷链状态" },
  { en: "Audit sugar costs", zh: "核算糖原料成本" },
  { en: "Retire low sellers", zh: "下架滞销口味" },
];

export default function SearchList({ lang: propLang }: { lang?: "en" | "zh" }) {
  const lang = useLang("search", propLang);
  const zh = lang === "zh";

  const [query, setQuery] = useState("");
  const labelOf = (item: (typeof ITEMS)[number]) => (zh ? item.zh : item.en);
  const results = query
    ? ITEMS.filter((i) => labelOf(i).toLowerCase().includes(query.toLowerCase()))
    : ITEMS.slice(0, 5);
  const empty = query.length > 2 && results.length === 0;

  return (
    <div className="flex min-h-[248px] w-full max-w-72 flex-col items-stretch">
      <div className="w-full self-start overflow-hidden rounded-card bg-surface shadow-raised">
        {/* input row */}
        <div className="flex h-10 items-center gap-2 border-b border-line px-3">
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="var(--ink-3)" strokeWidth="2" strokeLinecap="round" className="shrink-0">
            <circle cx="11" cy="11" r="7" />
            <path d="M21 21l-4.3-4.3" />
          </svg>
          <input
            value={query}
            onChange={(event) => setQuery(event.target.value)}
            placeholder={zh ? "搜索风味…" : "Search flavors…"}
            aria-label={zh ? "搜索风味" : "Search flavors"}
            className="min-w-0 flex-1 bg-transparent text-[13px] text-ink outline-none placeholder:text-ink-3"
          />
          {query && (
            <button
              aria-label={zh ? "清除搜索" : "Clear search"}
              type="button"
              onClick={() => setQuery("")}
              className="flex size-5.5 items-center justify-center rounded-full text-ink-3
                transition-colors duration-100 hover:bg-line/70 hover:text-ink"
              style={{ animation: "fade-in 150ms ease-out both" }}
            >
              <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round">
                <path d="M18 6L6 18M6 6l12 12" />
              </svg>
            </button>
          )}
        </div>

        {/* results / empty state */}
        {empty ? (
          <div className="flex flex-col items-center justify-center gap-1 px-4 py-8" style={{ animation: "fade-in 250ms ease-out both" }}>
            <span className="mb-1.5 flex size-8 items-center justify-center rounded-control bg-inset text-ink-3 shadow-hairline">
              <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round">
                <circle cx="11" cy="11" r="7" />
                <path d="M21 21l-4.3-4.3" />
              </svg>
            </span>
            <span className="text-[13px] font-medium text-ink">{zh ? "未找到相关结果" : "No results found"}</span>
            <span className="text-[12px] text-ink-3">{zh ? "换个关键词再试一次" : "Adjust your search to try again"}</span>
          </div>
        ) : (
          <div className="p-1">
            {results.map((item) => (
              <button
                key={item.en}
                type="button"
                onClick={() => setQuery(labelOf(item))}
                className="flex h-8 w-full items-center rounded-[6px] px-2 text-left text-[13px]
                  text-ink transition-colors duration-100 hover:bg-hover"
                style={{ animation: "fade-in 200ms ease-out both" }}
              >
                {labelOf(item)}
              </button>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import React, { createContext, useContext, useEffect, useState } from "react";

export type Lang = "en" | "zh";

interface LangContextType {
  globalLang: Lang;
  setGlobalLang: (lang: Lang) => void;
  componentLangs: Record<string, Lang>;
  setComponentLang: (id: string, lang: Lang) => void;
  getLang: (id?: string, override?: Lang) => Lang;
}

const LangContext = createContext<LangContextType>({
  globalLang: "en",
  setGlobalLang: () => {},
  componentLangs: {},
  setComponentLang: () => {},
  getLang: () => "en",
});

export function LangProvider({ children }: { children: React.ReactNode }) {
  const [globalLang, setGlobalLangState] = useState<Lang>("en");
  const [componentLangs, setComponentLangs] = useState<Record<string, Lang>>({});

  // Restore the persisted global language on mount.
  useEffect(() => {
    try {
      const stored = window.localStorage.getItem("nai-lang");
      if (stored === "en" || stored === "zh") setGlobalLangState(stored);
    } catch {}
  }, []);

  const setGlobalLang = (lang: Lang) => {
    setGlobalLangState(lang);
    try {
      window.localStorage.setItem("nai-lang", lang);
    } catch {}
  };

  const setComponentLang = (id: string, lang: Lang) => {
    setComponentLangs((prev) => ({ ...prev, [id]: lang }));
  };

  const getLang = (id?: string, override?: Lang): Lang => {
    if (override) return override;
    if (id && componentLangs[id]) return componentLangs[id];
    return globalLang;
  };

  return (
    <LangContext.Provider
      value={{
        globalLang,
        setGlobalLang,
        componentLangs,
        setComponentLang,
        getLang,
      }}
    >
      {children}
    </LangContext.Provider>
  );
}

export function useLang(id?: string, override?: Lang): Lang {
  const ctx = useContext(LangContext);
  return ctx.getLang(id, override);
}

export function useLangContext() {
  return useContext(LangContext);
}
